def is_palindrome(num):
    temp = num
    rev_num = 0
    while temp > 0:
        digit = temp % 10
        rev_num = rev_num * 10 + digit
        temp = temp // 10
    return rev_num == num


def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0
    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1
    return (even_count, odd_count)


