def get_max_triples(n):
    """
    You are given a positive integer n. You have to create an integer array a of length n.
        For each i (1 ≤ i ≤ n), the value of a[i] = i * i - i + 1.
        Return the number of triples (a[i], a[j], a[k]) of a where i < j < k, 
    and a[i] + a[j] + a[k] is a multiple of 3.

    Example :
        Input: n = 5
        Output: 1
        Explanation: 
        a = [1, 3, 7, 13, 21]
        The only valid triple is (1, 7, 13).
    """
    # Generate the array a
    a = [i * i - i + 1 for i in range(1, n + 1)]

    count = 0
    mod_0 = []
    mod_1 = []
    mod_2 = []

    # Classify elements of a into three categories based on their remainders when divided by 3
    for num in a:
        if num % 3 == 0:
            mod_0.append(num)
        elif num % 3 == 1:
            mod_1.append(num)
        else:
            mod_2.append(num)

    # Calculate the number of valid triples
    for i in mod_0:
        for j in mod_0:
            for k in mod_0:
                if (i + j + k) % 3 == 0:
                    count += 1
    for i in mod_1:
        for j in mod_1:
            for k in mod_2:
                if (i + j + k) % 3 == 0:
                    count += 1
    for i in mod_2:
        for j in mod_2:
            for k in mod_1:
                if (i + j + k) % 3 == 0:
                    count += 1

    return count


# Example usage
