        return len(set(word))

    max_word = ""
    for word in words:
        if unique_chars_count(word) > unique_chars_count(max_word):
            max_word = word
        elif unique_chars_count(word) == unique_chars_count(max_word):
            if word < max_word:
                max_word = word

