from typing import *
from math import sqrt


def is_prime(num: int) -> bool:
    if num < 2:
        return False
    for i in range(2, int(sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True


def factorize(n: int) -> List[int]:
    factors = []
    for i in range(2, int(sqrt(n)) + 1):
        while n % i == 0 and is_prime(i):
            factors.append(i)
            n //= i
    if n > 1 and is_prime(n):
        factors.append(n)
    return factors


