def median(l: list):
    """Return median of elements in the list l.
    >>> median([3, 1, 2, 4, 5])
    3
    >>> median([-10, 4, 6, 1000, 10, 20])
    15.0
    """
    n = len(l)
    if n == 0:
        return None
    sorted_l = sorted(l)
    mid = n // 2

    if n % 2 == 0:
        return (sorted_l[mid - 1] + sorted_l[mid]) / 2.0
    else:
        return float(sorted_l[mid])

